+        border-radius: 1rem;
+        background: #f9fbff;
+      }
+
+      .checkbox-row {
+        display: flex;
+        align-items: start;
+        gap: 0.875rem;
+      }
+
+      input[type="checkbox"] {
+        width: 1.15rem;
+        height: 1.15rem;
+        margin-top: 0.15rem;
+        accent-color: var(--primary);
+        flex: 0 0 auto;
+      }
+
+      label {
+        font-weight: 600;
+        line-height: 1.5;
+      }
+
+      a {
+        color: var(--primary-strong);
+      }
+
+      .helper-text,
+      .message {
+        font-size: 0.95rem;
+        line-height: 1.5;
+      }
+
+      .helper-text {
+        color: var(--muted);
+      }
+
+      .message {
+        margin: 0;
+        padding: 0.875rem 1rem;
+        border-radius: 0.9rem;
+      }
+
+      .message[hidden] {
+        display: none;
+      }
+
+      .message.error {
+        background: var(--error-bg);
+        color: var(--error-text);
+      }
+
+      .message.success {
+        background: var(--success-bg);
+        color: var(--success-text);
+      }
+
+      button {
+        border: 0;
+        border-radius: 999px;
+        padding: 0.95rem 1.2rem;
+        background: linear-gradient(180deg, var(--primary) 0%, var(--primary-strong) 100%);
+        color: #fff;
+        font: inherit;
+        font-weight: 700;
+        cursor: pointer;
+        transition: transform 120ms ease, box-shadow 120ms ease;
