    <style>
      :root {
        color-scheme: light;
        --bg: #f3f6fb;
        --panel: #ffffff;
        --panel-border: #d8e1f0;
        --text: #172033;
        --muted: #52607a;
        --primary: #2f6fed;
        --primary-strong: #1f57c7;
        --success-bg: #eaf8ef;
        --success-text: #165b2a;
        --error-bg: #fce8e8;
        --error-text: #8a1c1c;
        --shadow: 0 18px 50px rgba(23, 32, 51, 0.12);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, #dce8ff 0%, transparent 42%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        color: var(--text);
      }

