        position: absolute;
        left: 1rem;
        top: -3rem;
        padding: 0.75rem 1rem;
        border-radius: 0.75rem;
        background: var(--text);
        color: #fff;
        text-decoration: none;
      }

      .skip-link:focus-visible {
        top: 1rem;
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 1.5rem;
      }

      .card {
        width: min(100%, 28rem);
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        padding: 2rem;
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        color: var(--primary);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.75rem, 4vw, 2.25rem);
        line-height: 1.1;
      }

      .intro {
        margin: 0.875rem 0 1.5rem;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
        padding: 1rem;
        border: 1px solid var(--panel-border);
        border-radius: 1rem;
        background: #f9fbff;
      }

      .checkbox-row {
        display: flex;
        align-items: start;
        gap: 0.875rem;
      }

      input[type="checkbox"] {
        width: 1.15rem;
        height: 1.15rem;
        margin-top: 0.15rem;
        accent-color: var(--primary);
        flex: 0 0 auto;
      }

      label {
        font-weight: 600;
        line-height: 1.5;
      }

      a {
        color: var(--primary-strong);
      }

      .helper-text,
      .message {
        font-size: 0.95rem;
        line-height: 1.5;
      }

      .helper-text {
        color: var(--muted);
      }

      .message {
        margin: 0;
        padding: 0.875rem 1rem;
        border-radius: 0.9rem;
      }

      .message[hidden] {
        display: none;
      }

      .message.error {
        background: var(--error-bg);
        color: var(--error-text);
      }

      .message.success {
        background: var(--success-bg);
        color: var(--success-text);
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.2rem;
        background: linear-gradient(180deg, var(--primary) 0%, var(--primary-strong) 100%);
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition: transform 120ms ease, box-shadow 120ms ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 10px 20px rgba(47, 111, 237, 0.24);
      }

      a:focus-visible,
      input:focus-visible,
      button:focus-visible {
        outline: 3px solid var(--primary);
        outline-offset: 3px;
      }

      @media (max-width: 480px) {
        .card {
          padding: 1.5rem;
        }
      }

      @media (forced-colors: active) {
        .card,
        .form-field,
        button,
        .message {
          border: 1px solid ButtonText;
          box-shadow: none;
        }

        .card,
        .form-field,
        .message {
          background: Canvas;
          color: CanvasText;
        }

        button {
          background: ButtonFace;
          color: ButtonText;
        }

        a:focus-visible,
        input:focus-visible,
        button:focus-visible {
          outline-color: Highlight;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <section class="card" aria-labelledby="form-title">
        <p class="eyebrow">Setup</p>
        <h1 id="form-title">Confirm your consent</h1>
        <p class="intro">
          Please review and accept the terms of use before continuing.
        </p>

        <form id="consent-form" novalidate>
          <div class="form-field">
            <div class="checkbox-row">
              <input
                id="consent"
                name="consent"
                type="checkbox"
                required
                aria-describedby="consent-help consent-error"
              />
              <label for="consent">
                I agree to the <a href="#" target="_blank" rel="noopener noreferrer">terms of use</a>.
              </label>
            </div>
            <p class="helper-text" id="consent-help">
              Required to continue with your submission.
            </p>
          </div>

          <p
            id="consent-error"
            class="message error"
            hidden
            aria-live="assertive"
          >
            Please agree to the terms of use before submitting.
          </p>

          <p
            id="form-success"
            class="message success"
            hidden
            aria-live="polite"
          >
            Consent saved successfully.
          </p>

          <button type="submit">Submit</button>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("consent-form");
      const consent = document.getElementById("consent");
      const errorMessage = document.getElementById("consent-error");
      const successMessage = document.getElementById("form-success");

      function showError() {
        consent.setAttribute("aria-invalid", "true");
        errorMessage.hidden = false;
        successMessage.hidden = true;
      }

      function clearMessages() {
        consent.removeAttribute("aria-invalid");
        errorMessage.hidden = true;
      }

      consent.addEventListener("change", () => {
        if (consent.checked) {
          clearMessages();
        }
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!consent.checked) {
          showError();
          consent.focus();
          return;
        }

        clearMessages();
        successMessage.hidden = false;
      });
    </script>
  </body>
</html>
