               <label for="consent">I agree to the terms of use.</label>
             </div>
             <p class="helper-text" id="consent-help">
               Required to continue with your submission.
             </p>
           </div>

           <p
             id="consent-error"
             class="message error"
             hidden
             aria-live="assertive"
           >
             Please agree to the terms of use before submitting.
           </p>

           <p
             id="form-success"
             class="message success"
             hidden
             aria-live="polite"
           >
             Consent saved successfully.
           </p>

           <button type="submit">Submit</button>
         </form>
       </section>
     </main>

     <script>
       const form = document.getElementById("consent-form");
       const consent = document.getElementById("consent");
       const errorMessage = document.getElementById("consent-error");
       const successMessage = document.getElementById("form-success");

       function showError() {
         consent.setAttribute("aria-invalid", "true");
         errorMessage.hidden = false;
         successMessage.hidden = true;
       }

       function clearMessages() {
         consent.removeAttribute("aria-invalid");
         errorMessage.hidden = true;
       }

       consent.addEventListener("change", () => {
         if (consent.checked) {
           clearMessages();
         }
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         if (!consent.checked) {
           showError();
           consent.focus();
           return;
         }

         clearMessages();
         successMessage.hidden = false;
       });
     </script>
   </body>
 </html>

')
